class Solution:
    def removeValue(self, cells: List[int], blank: int) -> List[int]:
        a, n, i = cells[:], len(cells), 0
        while i < n:
            if a[i] == blank:
                for j in range(i, n - 1):
                    a[j] = a[j + 1]
                n -= 1
            else:
                i += 1
        return a[:n]

code.java:
class Solution {
    public int[] removeValue(int[] cells, int blank) {
        int[] a = cells.clone();
        int n = a.length, i = 0;
        while (i < n) {
            if (a[i] == blank) {
                for (int j = i; j < n - 1; j++) a[j] = a[j + 1];
                n--;
            } else i++;
        }
        return Arrays.copyOf(a, n);
    }
}

